import json
import os
import urllib.parse
import urllib.request

# The pricing service was moved from the retired prices.internal alias.
BASE = os.environ.get("PRICES_URL", "http://pricing-v2.internal:8081")


def get_price(sku: str) -> float:
    query = urllib.parse.urlencode({"sku": sku})
    request = urllib.request.Request(
        f"{BASE}/?{query}",
        headers={"X-Pricing-Key": os.environ["PRICING_KEY"]},
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
